{bold}{cyan}╔═══════════════════════════════════════════════════════════════╗{/cyan}{/bold}
{bold}{cyan}║{/cyan}{/bold}  {bold}{white}mip v{{version}}{/white}{/bold} - {gray}arrr, it be better than npm{/gray}        {bold}{cyan}║{/cyan}{/bold}
{bold}{cyan}║{/cyan}{/bold}  {gray}Plugins, Plunder and More Booty!{/gray}            {bold}{cyan}║{/cyan}{/bold}
{bold}{cyan}╚═══════════════════════════════════════════════════════════════╝{/cyan}{/bold}

{bold}{white}Captain's Orders:{/white}{/bold}
  {cyan}mip init{/cyan}                              {gray}Start a new treasure map{/gray}
  {cyan}mip install{/cyan} {gray}[pkg]{/gray}                     {gray}Plunder packages from the seven seas{/gray}
  {cyan}mip install -s{/cyan} {gray}[pkg]{/gray}                  {gray}SUPER FAST plunderin'{/gray}
  {cyan}mip uninstall{/cyan} {gray}<pkg>{/gray}                   {gray}Walk the plank, package!{/gray}
  {cyan}mip update{/cyan}                            {gray}Refresh ye loot{/gray}
  {cyan}mip list{/cyan}                              {gray}Show yer booty{/gray}

{bold}{white}Info:{/white}{/bold}
  {cyan}mip search{/cyan} {gray}<query>{/gray}                    {gray}Search for buried treasure{/gray}
  {cyan}mip info{/cyan} {gray}<pkg>{/gray}                        {gray}Show me the map, matey!{/gray}
  {cyan}mip outdated{/cyan}                           {gray}Show old, rotten cargo{/gray}
  {cyan}mip why{/cyan} {gray}<pkg>{/gray}                         {gray}Why be this here package?{/gray}

{bold}{white}Security:{/white}{/bold}
  {cyan}mip audit{/cyan}                             {gray}Check fer barnacles{/gray}
  {cyan}mip doctor{/cyan}                            {gray}Scurvy diagnosis{/gray}

{bold}{white}Development:{/white}{/bold}
  {cyan}mip create{/cyan} {gray}<template> <name>{/gray}          {gray}Build a new ship{/gray}
  {cyan}mip run{/cyan} {gray}<script>{/gray}                      {gray}Run the sails up!{/gray}
  {cyan}mip exec{/cyan} {gray}<cmd>{/gray}                        {gray}Execute the first mate's orders{/gray}
  {cyan}mip link{/cyan}                              {gray}Tie the ships together{/gray}

{bold}{white}Aliases:{/white}{/bold}
  {cyan}mip alias set{/cyan} {gray}<name> <command>{/gray}        {gray}Give 'em a new name{/gray}
  {cyan}mip alias remove{/cyan} {gray}<name>{/gray}               {gray}Erase their name from history{/gray}
  {cyan}mip alias list{/cyan}                           {gray}Show all crew members{/gray}
  {cyan}mip alias clear{/cyan}                          {gray}Throw 'em all overboard{/gray}

{bold}{white}Monorepo:{/white}{/bold}
  {cyan}mip workspaces list{/cyan}                   {gray}Show the fleet{/gray}
  {cyan}mip workspaces run{/cyan} {gray}<script>{/gray}           {gray}All hands on deck!{/gray}

{bold}{white}Maintenance:{/white}{/bold}
  {cyan}mip cache clean{/cyan}                       {gray}Scrub the decks clean{/gray}
  {cyan}mip cache size{/cyan}                        {gray}How big be me treasure?{/gray}
  {cyan}mip ci{/cyan}                                {gray}Prepare for battle!{/gray}
